#[component]
fn Welcome(name: String) -> impl IntoView {
    view! {
        <div>
            <h1>"Welcome, " {name} "!"</h1>
            <p>"Enjoy your Tauri app."</p>
        </div>
    }
}

view! {
    <ul>
        <For
            each=move || items()
            key=|item| item.id
            children=|item| view! { <li>{item.name}</li> }
        />
    </ul>
}
